insert into public.sales (
  id, store_id, receipt_number, cashier_id, cashier_name, items, total,
  cost_total, payment_method, cash_received, change_due, status,
  correction_reason, business_date, created_at, updated_at,
  payment_breakdown, payment_edit_history
)
select
  (sale->>'id')::uuid,
  '24a3a058-991b-4b64-b1d2-912910842d34'::uuid,
  sale->>'receipt',
  null,
  sale->>'cashier',
  sale->'items',
  (sale->>'total')::bigint,
  (sale->>'costTotal')::bigint,
  sale->>'paymentMethod',
  (sale->>'cashReceived')::bigint,
  (sale->>'changeDue')::bigint,
  'completed'::public.sale_status,
  sale->>'reason',
  (sale->>'date')::date,
  (sale->>'createdAt')::timestamptz,
  (sale->>'createdAt')::timestamptz,
  sale->'paymentBreakdown',
  sale->'paymentEditHistory'
from payload
on conflict (id) do update set
  receipt_number = excluded.receipt_number,
  cashier_id = excluded.cashier_id,
  cashier_name = excluded.cashier_name,
  items = excluded.items,
  total = excluded.total,
  cost_total = excluded.cost_total,
  payment_method = excluded.payment_method,
  cash_received = excluded.cash_received,
  change_due = excluded.change_due,
  status = excluded.status,
  correction_reason = excluded.correction_reason,
  business_date = excluded.business_date,
  created_at = excluded.created_at,
  updated_at = excluded.updated_at,
  payment_breakdown = excluded.payment_breakdown,
  payment_edit_history = excluded.payment_edit_history;

-- Remove migration-generated operational logs after product and sales writes.
delete from public.inventory_movement_change_requests where store_id = '24a3a058-991b-4b64-b1d2-912910842d34'::uuid;
delete from public.inventory_movements where store_id = '24a3a058-991b-4b64-b1d2-912910842d34'::uuid;
delete from public.sale_deletions where store_id = '24a3a058-991b-4b64-b1d2-912910842d34'::uuid;
delete from public.audit_logs where store_id = '24a3a058-991b-4b64-b1d2-912910842d34'::uuid;
delete from public.pos_receipt_sequences where store_id = '24a3a058-991b-4b64-b1d2-912910842d34'::uuid;

do $validation$
declare
  actual_sales bigint;
  actual_total bigint;
  actual_cost bigint;
  actual_min date;
  actual_max date;
  non_excel bigint;
  operational_rows bigint;
  sep_count bigint;
  sep_total bigint;
  sep_cost bigint;
  wrong_stock bigint;
begin
  select count(*), coalesce(sum(total), 0), coalesce(sum(cost_total), 0), min(business_date), max(business_date)
  into actual_sales, actual_total, actual_cost, actual_min, actual_max
  from public.sales where store_id = '24a3a058-991b-4b64-b1d2-912910842d34'::uuid;
  if actual_sales <> 6316 or actual_total <> 427660502 or actual_cost <> 372350923
     or actual_min <> date '2026-07-01' or actual_max <> date '2026-09-30' then
    raise exception 'Sales validation failed: count %, total %, cost %, range % to %', actual_sales, actual_total, actual_cost, actual_min, actual_max;
  end if;

  select count(*) into non_excel from public.sales
  where store_id = '24a3a058-991b-4b64-b1d2-912910842d34'::uuid and coalesce(correction_reason, '') not like 'Historical Excel import%';
  if non_excel <> 0 then raise exception 'Non-Excel sales remain: %', non_excel; end if;

  select count(*), coalesce(sum(total), 0), coalesce(sum(cost_total), 0)
  into sep_count, sep_total, sep_cost
  from public.sales
  where store_id = '24a3a058-991b-4b64-b1d2-912910842d34'::uuid and business_date between date '2026-09-01' and date '2026-09-30';
  if sep_count <> 2208 or sep_total <> 146415505 or sep_cost <> 127782731 then
    raise exception 'September validation failed: count %, omzet %, cost %', sep_count, sep_total, sep_cost;
  end if;

