    (select count(*) from public.inventory_movements where store_id = '24a3a058-991b-4b64-b1d2-912910842d34'::uuid) +
    (select count(*) from public.sale_deletions where store_id = '24a3a058-991b-4b64-b1d2-912910842d34'::uuid) +
    (select count(*) from public.audit_logs where store_id = '24a3a058-991b-4b64-b1d2-912910842d34'::uuid) +
    (select count(*) from public.cash_closings where store_id = '24a3a058-991b-4b64-b1d2-912910842d34'::uuid) +
    (select count(*) from public.receivings where store_id = '24a3a058-991b-4b64-b1d2-912910842d34'::uuid) +
    (select count(*) from public.expenses where store_id = '24a3a058-991b-4b64-b1d2-912910842d34'::uuid) +
